+  const name = `${segment}_${field}`
+    .replace(/[^A-Za-z0-9]+/g, "_")
+    .replace(/^_+|_+$/g, "")
+    .toUpperCase();
+  if (name === "") throw new RangeError(`no variable name can be built from ${JSON.stringify([path, field])}`);
+  return /^[0-9]/.test(name) ? `_${name}` : name;
 }
+
+const NAME_PATTERN = /^[A-Z_][A-Z0-9_]*$/;
+const PLAIN_VALUE = /^[A-Za-z0-9_@%+=:,./-]*$/;
+const ESCAPES: Record<string, string> = { "\\": "\\\\", '"': '\\"', $: "\\$", "\n": "\\n", "\r": "\\r" };

 /** Render variables as the lines of a dotenv file. */
 export function renderEnvFile(vars: Record<string, string>): string {
-  throw new Error("not implemented");
+  const names = Object.keys(vars).sort();
+  for (const name of names) {
+    if (!NAME_PATTERN.test(name)) throw new RangeError(`invalid variable name: ${JSON.stringify(name)}`);
+  }
+  return names
+    .map((name) => {
+      const value = vars[name];
+      const text = PLAIN_VALUE.test(value) ? value : `"${value.replace(/[\\"$\n\r]/g, (c) => ESCAPES[c])}"`;
+      return `${name}=${text}\n`;
+    })
+    .join("");
 }

